 using namespace actual_problem_probe_v1;const char*key="audit_actual_observability_v1";if(!cfg.contains(key))return {{"enabled",false}};const auto&policy=cfg.at(key);if(!cfg.value("source_uv_capture_preflight_only",false)||policy.at("schema")!="rinkfit.actual_objective_observability_probe.v1")throw std::runtime_error("actual observability probe is an explicit preflight-only diagnostic");
 const auto started=std::chrono::steady_clock::now();std::size_t pixels=0;for(const auto&r:b.core.packet.rows)pixels+=r.active;const auto motion=b.static_motion?b.static_motion->rows.size():0;if(inv.statistical_blocks.size()!=pixels+motion)throw std::runtime_error("actual observability statistical inventory does not match full selected source and motion");
 std::unordered_map<ceres::ResidualBlockId,Family>family;for(std::size_t k=0;k<inv.statistical_blocks.size();++k)family[static_cast<ceres::ResidualBlockId>(inv.statistical_blocks[k])]=k<pixels?Family::Pixel:Family::Motion;for(auto id:inv.inequality_blocks)family[static_cast<ceres::ResidualBlockId>(id)]=Family::Domain;for(auto id:inv.equality_blocks)family[static_cast<ceres::ResidualBlockId>(id)]=Family::Equality;
 std::unordered_map<double*,int>physical;for(std::size_t i=0;i<b.core.model.blocks.size();++i)physical[b.core.model.blocks[i].values.data()]=int(i);std::unordered_map<double*,std::size_t>motion_pointer;if(b.static_motion)for(std::size_t i=0;i<b.static_motion->rows.size();++i)motion_pointer[b.static_motion->rows[i].latent.data()]=i;
 auto span=[](double*x,const std::vector<double>&values)->std::int64_t{if(values.empty())return -1;const auto a=reinterpret_cast<std::uintptr_t>(x),base=reinterpret_cast<std::uintptr_t>(values.data()),bytes=values.size()*sizeof(double);return a>=base&&a-base<bytes&&(a-base)%sizeof(double)==0?std::int64_t((a-base)/sizeof(double)):-1;};std::size_t unknown_aux=0;
 auto metadata=[&](double*x,int n){const auto found=physical.find(x);if(found!=physical.end()){const auto&v=b.core.model.blocks[found->second];const auto&name=v.name;const std::string role=name.rfind("print_vertex/",0)==0?"static_unmeasured_print_vertex":name.rfind("print_envelope/",0)==0?"numerical_course_envelope":name.rfind("ad/",0)==0?"advertisement_installation":name.rfind("rig/",0)==0?"camera_rig_optics":name.rfind("shot/",0)==0?"camera_trajectory":found->second==b.core.model.scene_block?"common_rink_scene":"other_model_physical";return Metadata{name,role,v.scales};}if(n==1){for(const auto&entry:std::vector<std::pair<const std::vector<double>*,const char*>>{{&b.core.station,"station"},{&b.core.row,"row"},{&b.core.alpha,"alpha"}}){const auto i=span(x,*entry.first);if(i>=0)return Metadata{std::string(entry.second)+"/"+std::to_string(i),std::string("raw_auxiliary_")+entry.second,{1.}};}if(x==b.budget_parameter())return Metadata{"budget_sq","unused_engineering_budget",{1.}};}const auto mi=motion_pointer.find(x);if(mi!=motion_pointer.end())return Metadata{"static_motion/"+std::to_string(mi->second),"unmeasured_static_surface_latent",std::vector<double>(n,1.)};return Metadata{"actual_extra/"+std::to_string(unknown_aux++),"unregistered_auxiliary_unit_metric",std::vector<double>(n,1.)};};
 // Hash the actual graph's complete parameter registry and all full raw
