 std::vector<double*>all;p.GetParameterBlocks(&all);std::sort(all.begin(),all.end(),std::less<double*>{});std::vector<int>sizes;for(auto*x:all)sizes.push_back(p.ParameterBlockSize(x));
 auto token=[&]{eventio::FastSHA256Stream h;auto add=[&](const void*x,std::size_t n){h.update(static_cast<const std::uint8_t*>(x),n);};for(std::size_t k=0;k<all.size();++k)add(all[k],std::size_t(sizes[k])*sizeof(double));for(const auto*v:{&b.core.station,&b.core.row,&b.core.alpha})add(v->data(),v->size()*sizeof(double));for(const auto&r:b.core.packet.rows){add(&r.path,sizeof(r.path));add(&r.numerical_shape_segment,sizeof(r.numerical_shape_segment));}const auto identity=b.identity();for(const auto*s:{&identity.source_id,&identity.model_id,&identity.objective_id,&identity.statistics_id,&identity.scales_id})add(s->data(),s->size());const auto global=b.engineering_global_phr_state_v1.json().dump();add(global.data(),global.size());return h.finish();};
