 auto find=[&](int a){while(parent.at(a)!=a){parent[a]=parent.at(parent.at(a));a=parent.at(a);}return a;};for(const auto&mat:b.core.model.materials)for(const auto&path:mat.paths)if(path.kind==6&&!path.vertex_blocks.empty()){const int ad=path.advertisement_block;parent.emplace(ad,ad);ad_envelopes[ad].insert(path.course_envelope_block);for(int vi:path.vertex_blocks){ad_vertices[ad].insert(vi);auto old=vertex_ad.find(vi);if(old==vertex_ad.end())vertex_ad[vi]=ad;else parent[find(ad)]=find(old->second);}}
 std::map<int,std::vector<int>>components;for(const auto&entry:parent)components[find(entry.first)].push_back(entry.first);for(auto&entry:components){auto&ads=entry.second;std::sort(ads.begin(),ads.end());std::set<int>vertices,envelopes;for(int ad:ads){vertices.insert(ad_vertices[ad].begin(),ad_vertices[ad].end());envelopes.insert(ad_envelopes[ad].begin(),ad_envelopes[ad].end());}
  for(int mode=0;mode<4;++mode){std::unordered_map<double*,std::vector<double>>ambient;for(int vi:vertices){auto&v=b.core.model.blocks.at(vi).values;std::vector<double>d(2,0);if(mode==0)d[0]=1.;if(mode==1)d[0]=v[0];if(mode==2)d[1]=1.;if(mode==3)d[1]=v[1];ambient[v.data()]=std::move(d);}for(int ei:envelopes){auto&v=b.core.model.blocks.at(ei).values;if(mode<2)ambient[v.data()]=mode==0?std::vector<double>{1.,1.}:v;}
   for(int ai:ads){auto&v=b.core.model.blocks.at(ai).values;std::vector<double>d(v.size(),0);for(std::size_t off=0;off+4<=v.size();off+=4){const double W=v[off+1],H=v[off+3]-v[off+2];if(mode==0)d[off]=-W;if(mode==1)d[off+1]=-W;if(mode==2)d[off+2]=d[off+3]=-H;if(mode==3)d[off+3]=-H;}ambient[v.data()]=std::move(d);}
   static const char*names[]={"u_translation","u_scale","v_translation","v_scale"};const auto name="ad_component/"+std::to_string(entry.first)+"/"+names[mode];try{directions.push_back(op.ambient_direction(name,ambient,{{"kind","candidate_normalized_print_chart_reparameterization"},{"advertisement_blocks",ads},{"static_vertex_blocks",vertices.size()},{"numeric_envelope_blocks",envelopes.size()},{"rectangular_boundary_pixel_and_actual_global_terms_retained",true},{"is_predeclared_gauge_or_physical_truth",false}},true));}catch(const std::exception&e){rejected.push_back({{"direction",name},{"reason",e.what()},{"actual_fixed_or_manifold_chart_excluded_direction",true},{"physical_rank_certified",false}});}
  }
 }
 if(directions.empty())throw std::runtime_error("actual observability preflight has no legal static chart candidates");std::filesystem::create_directories(out);const auto first=op.apply(directions.front(),true);eventio::atomic_json(out/"actual_operator_column_support.json",first.report);
 auto binary=[&](const char*name,const std::vector<std::uint8_t>&data){const auto path=out/name;std::ofstream f(path,std::ios::binary);f.write(reinterpret_cast<const char*>(data.data()),std::streamsize(data.size()));if(!f)throw std::runtime_error("cannot write exact actual column support mask");f.close();return Json{{"file",path.string()},{"sha256",eventio::file_sha256(path)},{"dtype","|u1"},{"shape",{data.size()}},{"zero_means_exactly_no_nonzero_actual_Jacobian_coefficient",true}};};Json support={{"pixel",binary("pixel_column_nonzero.u8",first.pixel_column_nonzero)},{"pixel_plus_motion",binary("measurement_column_nonzero.u8",first.measurement_column_nonzero)},{"full_target",binary("full_target_column_nonzero.u8",first.full_column_nonzero)}};
 Json shape_columns=Json::array();for(const auto&v:op.blocks()){const auto it=physical.find(v.address);if(it!=physical.end()&&v.metadata.role=="static_unmeasured_print_vertex")shape_columns.push_back(Json::array({it->second,v.offset,v.tangent}));}eventio::atomic_json(out/"static_vertex_actual_column_order.json",{{"schema","rinkfit.actual_static_vertex_column_order.v1"},{"columns",shape_columns},{"tuple_fields",{"model_block_index","actual_tangent_column_offset","actual_tangent_size"}},{"support_masks",support}});
 const auto gram=op.gram(directions);eventio::atomic_json(out/"actual_chart_direction_gram.json",gram.report);Eigen::GeneralizedSelfAdjointEigenSolver<Eigen::MatrixXd>e(gram.full,gram.metric);if(e.info()!=Eigen::Success)throw std::runtime_error("actual full-target candidate Ritz solve failed");const auto weakest=op.linear_combination("weakest_within_actual_finite_chart_probe_span",directions,e.eigenvectors().col(0));const auto weak=op.apply(weakest,false);eventio::atomic_json(out/"actual_weakest_chart_direction.json",weak.report);
 return {{"schema","rinkfit.actual_whole_objective_observability_preflight.v1"},{"enabled",true},{"complete_parameter_raw_auxiliary_discrete_global_digest",token()},{"selected_source_rows",pixels},{"static_motion_factors",motion},{"actual_tangent_columns",op.columns()},{"candidate_directions",directions.size()},{"excluded_candidates",rejected},{"unregistered_auxiliary_scale_metadata",unknown_aux},{"source_vs_domain_family_coverage_complete",first.report.at("source_vs_domain_family_coverage_complete")},{"column_support",first.report.at("column_support")},{"support_masks",support},{"full_finite_span_spectrum",gram.report.at("complete_target_span")},{"pixel_finite_span_spectrum",gram.report.at("pixel_span")},{"weakest_finite_span_JtJv_norm",weak.report.at("full_JtJv_norm")},{"seconds",std::chrono::duration<double>(std::chrono::steady_clock::now()-started).count()},{"actual_current_problem_W_motion_PHR_and_manifolds_consumed",true},{"actual_source_uv_objective_id",b.identity().objective_id},{"observed_row_initialization_scope",b.source_uv_observed_row_initialization()},{"formal_Query_or_true_RS_certified",false},{"state_digest_is_native_checkpoint_token",false},{"full_graph_rank_or_physical_shape_identifiability_certified",false},{"local_cell_and_current_working_set_scope_only",true},{"station_Schur_or_critical_cone_certificate_performed",false},{"large_global_J_matrix_written",false},{"source_model_or_accepted_state_changed",false},{"quality_accepted",false}};
